t = int(input())
for i in range(t):
	(n, k) = [int(j) for j in input().split()]
	b = set()
	flag = 0
	cout = 0
	for m in range(n):
		a = [int(j) for j in input().split()]
		a1 = a[1:]
		cout += 1
		if flag == 1:
			continue
		b.update(a1)
		if len(b) == k:
			flag = 1
			if cout == n:
				print('all')
			else:
				print('some')
	if flag == 0:
		print('sad')
